    responses: {
      /** @description Saved assignment and auto-fix outcome. Human assignment is manual. The selected Agent autoFix setting controls the trigger. */
      200: {
        headers: {
          /** @description The supplied or generated command ID. Reuse it for retries. */
          "Idempotency-Key"?: string;
        };
        content: {
          "application/json": {
            item: {
              id: string;
              title: string;
              description: string;
              successCriteria: string[];
              subtasks: {
                items: {
                    id: string;
                    title: string;
                    done: boolean;
                  }[];
                completed: number;
              };
              /** @enum {string} */
              status: "todo" | "in_progress" | "in_review" | "done";
              /** @enum {string} */
              priority: "low" | "medium" | "high" | "critical";
              assignee: "needs_human" | `needs_agent_${string}`;
              reporter: string;
              /** Format: date */
              startDate: string | null;
              /** Format: date */
              dueDate: string | null;
              sprint: string | null;
              parent: string | null;
              labels: string[];
              team: string;
              watchers: string[];
              /** @enum {string} */
              severity: "info" | "warning" | "critical";
              service: string;
              diagnosisRef: string;
              fixPriority: number;
              draftPr: {
                repo: string;
                number: number;
                url: string;
                branch: string;
                headSha: string;
              } | null;
            };
            autoFix: ({
              ok: boolean;
              /** @enum {string} */
              effect: "allow" | "deny" | "require_approval" | "dry_run";
              reason: string | null;
              /** @enum {string} */
              failure: "none" | "auto_fix_disabled" | "context_unavailable" | "invalid_context" | "policy_denied" | "patch_rejected" | "pr_failed" | "fix_error" | "already_fixed" | "awaiting_answer" | "needs_human" | "routing_failed" | "audit_failed" | "publication_uncertain";
              routing: OneOf<[{
                /** @enum {string} */
                kind: "routed";
                agent: {
                  name: string;
                  slug: string;
                };
              }, {
                /** @enum {string} */
                kind: "ask";
                agent: {
                  name: string;
                  slug: string;
                };
                questionId: string;
                question: string;
                missing: string[];
              }, {
                /** @enum {string} */
                kind: "needs_human";
                agent: string;
                reason: string;
                missing: string[];
              }, null]>;
              attemptId: string | null;
            }) | null;
          };
        };
      };
      /** @description A management access token is required. */
      401: {
        content: never;
      };
      /** @description The token does not hold fix:trigger, so triage cannot start an automatic Fix. */
      403: {
        content: never;
      };
      /** @description The Work item does not exist in this project. */
      404: {
        content: never;
      };
      /** @description The Work item is complete, has an active attempt, or the command ID conflicts. */
      409: {
        content: never;
      };
      /** @description The assignee is invalid or the Agent is unknown. */
      422: {
        content: never;
      };
    };
